using DriveOS.Modules.CurriculumPedagogy.Domain.Curricula;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;
namespace DriveOS.Modules.CurriculumPedagogy.Infrastructure.Persistence.Repositories;
internal sealed class CurriculumRepository(CurriculumPedagogyDbContext db):ICurriculumRepository
{private IQueryable<Curriculum> Graph=>db.Curricula.Include(x=>x.Versions).ThenInclude(x=>x.Modules).ThenInclude(x=>x.Competencies);public Task<Curriculum?> GetByIdAsync(CurriculumId id,CancellationToken ct=default)=>Graph.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,ct);public Task<Curriculum?> GetByIdForUpdateAsync(CurriculumId id,CancellationToken ct=default)=>Graph.SingleOrDefaultAsync(x=>x.Id==id,ct);public Task<bool> ExistsByCodeAsync(OrganizationId org,string code,CancellationToken ct=default)=>db.Curricula.AsNoTracking().AnyAsync(x=>x.OrganizationId==org&&x.Code==code.Trim().ToUpperInvariant(),ct);public async Task AddAsync(Curriculum x,CancellationToken ct=default)=>await db.Curricula.AddAsync(x,ct);}
